import{_ as t,o,c as e,a0 as r}from"./chunks/framework.Caz7a20Z.js";const c=JSON.parse('{"title":"论文整理完毕，多智能体跑通，数据下载还有坑","description":"今天把论文相关的东西都整理完了，多智能体也终于能跑通了；就是数据下载那块还有点问题，留到明天修。明天还得把论文整体再过一遍收尾。","frontmatter":{"title":"论文整理完毕，多智能体跑通，数据下载还有坑","date":"2026-08-27T00:00:00.000Z","tags":["日记"],"description":"今天把论文相关的东西都整理完了，多智能体也终于能跑通了；就是数据下载那块还有点问题，留到明天修。明天还得把论文整体再过一遍收尾。"},"headers":[],"relativePath":"posts/diary-20260827.md","filePath":"posts/diary-20260827.md","lastUpdated":null}'),s={name:"posts/diary-20260827.md"};function n(i,a,l,d,p,u){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="论文整理完毕-多智能体跑通-数据下载还有坑" tabindex="-1">论文整理完毕，多智能体跑通，数据下载还有坑 <a class="header-anchor" href="#论文整理完毕-多智能体跑通-数据下载还有坑" aria-label="Permalink to &quot;论文整理完毕，多智能体跑通，数据下载还有坑&quot;">​</a></h1><p>今天算是把论文那一摊子&quot;整理&quot;的活儿给收拾干净了 🎉。</p><h2 id="论文-能收拾的都收拾了" tabindex="-1">论文：能收拾的都收拾了 <a class="header-anchor" href="#论文-能收拾的都收拾了" aria-label="Permalink to &quot;论文：能收拾的都收拾了&quot;">​</a></h2><p>之前零散的代码、中间产物、补的材料，今天一股脑理清楚、归好位。该归档的归档、该清掉的清掉，整个项目比前两天清爽多了。<strong>论文本身的东西算是整理完毕</strong>——当然，&quot;整理完&quot;和&quot;改完&quot;是两码事，内容还是昨天那一版，没动正文。</p><h2 id="多智能体-终于跑通了" tabindex="-1">多智能体：终于跑通了 <a class="header-anchor" href="#多智能体-终于跑通了" aria-label="Permalink to &quot;多智能体：终于跑通了&quot;">​</a></h2><p>更开心的是，<strong>多智能体这次真能跑通了</strong> 🚀。前面卡了挺久的环节，今天总算理顺，端到端能走下来、能出结果。虽然离&quot;完美&quot;还有距离，但&quot;能跑&quot;这个坎儿算是迈过去了，爽。</p><h2 id="但数据下载是个坑" tabindex="-1">但数据下载是个坑 <a class="header-anchor" href="#但数据下载是个坑" aria-label="Permalink to &quot;但数据下载是个坑&quot;">​</a></h2><p>高兴归高兴，还是留了个尾巴：<strong>数据下载这块有问题</strong>。具体是下载环节不太稳，要么是源不对、要么是流程卡壳，反正没能顺下来。这种&quot;差最后一块&quot;的感觉最磨人，但没有今晚硬刚，留到明天专门收拾它。</p><h2 id="明天的活儿" tabindex="-1">明天的活儿 <a class="header-anchor" href="#明天的活儿" aria-label="Permalink to &quot;明天的活儿&quot;">​</a></h2><p>两件事：</p><ol><li><strong>修数据下载</strong>——把下载那块的问题定位、修掉；</li><li><strong>论文整体整理</strong>——把整篇再过一遍，从大到小理一遍，争取正式收尾。</li></ol><p>今天先到这儿，嘿嘿，能跑通的瞬间还是挺上头的 😄。明天继续，加油！</p>',12)])])}const q=t(s,[["render",n]]);export{c as __pageData,q as default};
